// apply_routing_rules: decides whether the package is approved or rejected automatically,
// or goes to a human. The rules are fixed code, so routing never depends on how the AI
// words its answer.
//
// Inputs:  $.evidenceText   the evidence pack from build_evidence_pack, as JSON text
//          $.assessment     the AI's answer (only its verdict is used here)
// Output:  verdict, llmOutputValid, highOrCriticalAdvisories,
//          route ("AUTO_APPROVE", "AUTO_REJECT" or "HUMAN_REVIEW"),
//          routeReasons (why it wasn't auto-approved), rejectReasons (the facts behind an auto-rejection)
//
// Notes on Conductor:
// - The last line calls applyRoutingRules(); what it returns becomes the task output.
//   Everything else is inside functions, because a top-level const or let can fail when
//   Conductor reuses a script context.
// - Text is joined with + because Conductor treats a dollar sign followed by a brace in a
//   task input as a workflow reference, which rules out JavaScript template literals.
// - The evidence arrives as JSON text, so JSON.parse gives plain JavaScript objects and arrays.

// plural(1, "known advisory", "known advisories") -> "1 known advisory"
function plural(count, one, many) {
  if (count === 1) {
    return count + " " + one;
  }
  return count + " " + many;
}

function isHighOrCritical(advisory) {
  return advisory.severity === "HIGH" || advisory.severity === "CRITICAL";
}

// "request@2.88.2" -> "request", "@strapi/strapi@5.58.0" -> "@strapi/strapi"
function nameOf(packageRef) {
  return packageRef.substring(0, packageRef.lastIndexOf("@"));
}

// A deprecation message in quotes, cut to 120 characters, e.g. ' ("request has been deprecated, …")'
function quoted(message) {
  if (!message) {
    return "";
  }
  return " (\"" + message.substring(0, 120) + "\")";
}

function applyRoutingRules() {
  const evidence = JSON.parse($.evidenceText);
  const deps = evidence.transitiveDependencies;
  const policy = evidence.licensePolicy;

  // ---- The AI's verdict ----

  // If the model returned text instead of JSON, try to parse it.
  let assessment = $.assessment || {};
  if (typeof assessment === "string") {
    try {
      assessment = JSON.parse(assessment);
    } catch (e) {
      assessment = {};
    }
  }

  // e.g. " adopt " -> "ADOPT". Anything other than the three verdicts becomes NEEDS_REVIEW,
  // so a human decides.
  const said = String(assessment.verdict || "").trim().toUpperCase();
  const llmOutputValid = said === "ADOPT" || said === "ADOPT_WITH_CONDITIONS" || said === "AVOID";
  let verdict = "NEEDS_REVIEW";
  if (llmOutputValid) {
    verdict = said;
  }

  // ---- Facts the rules use ----

  const onPackage = evidence.advisories.length;
  const inDependencies = deps.uniqueAdvisoryCount;
  const totalAdvisories = onPackage + inDependencies;

  // High or critical advisories: the package's own, plus those in its dependencies.
  let ownHighOrCritical = 0;
  for (const advisory of evidence.advisories) {
    if (isHighOrCritical(advisory)) {
      ownHighOrCritical++;
    }
  }
  const highOrCritical = ownHighOrCritical + deps.highOrCriticalAdvisories;

  // The package's own high or critical advisories have no single fix if the workflow
  // couldn't compute an upgrade version.
  const ownUnfixed = ownHighOrCritical > 0 && !evidence.upgrade.recommendedVersion;

  // Packages with high or critical advisories that no single upgrade fixes, e.g. ["braces@3.0.3"].
  const unfixed = [];
  if (ownUnfixed) {
    unfixed.push(evidence.package);
  }
  for (const name of deps.unfixedHighOrCritical) {
    unfixed.push(name);
  }

  // Missing sources that matter for security, e.g. ["OSV.dev (HTTP)"]. Missing DeepWiki
  // notes or download counts don't block approval.
  const securityGaps = [];
  for (const source of evidence.missingSources) {
    if (source.includes("OSV") || source.includes("GetDependencies") || source.includes("GetVersionBatch")) {
      securityGaps.push(source);
    }
  }

  // ---- The rules: auto-approval needs all five to pass ----

  // Each failed rule adds a reason, which the reviewer and the GitHub issue will see.
  const reasons = [];

  // Rule 1: the AI must say ADOPT.
  // e.g. "AI verdict is ADOPT_WITH_CONDITIONS"
  if (verdict !== "ADOPT") {
    reasons.push("AI verdict is " + verdict);
  }

  // Rule 2: every license must be allowed and recognized.
  // e.g. "3 package(s) use licenses outside the allowed list"
  if (policy.violationCount > 0) {
    reasons.push(policy.violationCount + " package(s) use licenses outside the allowed list");
  }
  // e.g. "25 package(s) have unknown or non-standard licenses"
  if (policy.unknownCount > 0) {
    reasons.push(policy.unknownCount + " package(s) have unknown or non-standard licenses");
  }

  // Rule 3: no known advisories, on the package or on any dependency.
  // e.g. "13 known advisories (0 on the package, 13 in dependencies), 4 of them high or critical"
  if (totalAdvisories > 0) {
    let reason = plural(totalAdvisories, "known advisory", "known advisories");
    reason += " (" + onPackage + " on the package, " + inDependencies + " in dependencies)";
    if (highOrCritical > 0) {
      // "at least" when some severities couldn't be looked up.
      if (deps.severityComplete) {
        reason += ", " + highOrCritical + " of them high or critical";
      } else {
        reason += ", at least " + highOrCritical + " of them high or critical";
      }
    }
    reasons.push(reason);
  }

  // Not a separate rule (any advisory already needs a human), but the reviewer should know.
  // e.g. "no single upgrade fixes the high or critical advisories in braces@3.0.3"
  if (unfixed.length > 0) {
    reasons.push("no single upgrade fixes the high or critical advisories in " + unfixed.join(", "));
  }

  // Rule 4: the security evidence must be complete.
  // e.g. "only 199 of 269 dependencies were checked"
  if (deps.checked < deps.total) {
    reasons.push("only " + deps.checked + " of " + deps.total + " dependencies were checked");
  }
  // e.g. "security evidence unavailable (OSV.dev (HTTP))"
  if (securityGaps.length > 0) {
    reasons.push("security evidence unavailable (" + securityGaps.join(", ") + ")");
  }

  // Rule 5: the package must not be deprecated, in this version or as a whole. Deprecation
  // always needs a human, even if the AI says ADOPT.
  if (evidence.isDeprecated) {
    // e.g. 'ua-parser-js@1.0.2 is deprecated ("You are using an outdated version of ua-parser-js…")'
    reasons.push(evidence.package + " is deprecated" + quoted(evidence.deprecatedReason));
  } else if (evidence.latestVersionDeprecated === true) {
    // e.g. "request is deprecated in its latest version, 2.88.2"
    reasons.push(nameOf(evidence.package) + " is deprecated in its latest version, " + evidence.latestVersion);
  }

  // ---- Automatic rejection ----

  // First, facts that rule the package out on their own, whatever the AI says.
  const rejectReasons = [];
  if (evidence.latestVersionDeprecated === true) {
    // e.g. 'request is deprecated by its maintainers, including its latest version 2.88.2 ("request has been deprecated, …")'
    rejectReasons.push(nameOf(evidence.package) + " is deprecated by its maintainers, including its latest version " +
      evidence.latestVersion + quoted(evidence.latestDeprecatedReason));
  }
  for (const advisory of evidence.advisories) {
    if (advisory.id.startsWith("MAL-")) {
      // e.g. "chalk@5.6.1 is listed as malicious (MAL-2025-46969)"
      rejectReasons.push(evidence.package + " is listed as malicious (" + advisory.id + ")");
    } else if (advisory.severity === "CRITICAL" && !advisory.hasFix) {
      // e.g. "node-serialize@0.0.4 has a CRITICAL advisory with no fixed version (GHSA-q4v7-4rhw-9hqm)"
      rejectReasons.push(evidence.package + " has a CRITICAL advisory with no fixed version (" + advisory.id + ")");
    }
  }

  // Then, weaker facts that reject only when the AI also says AVOID: this version is deprecated,
  // or it has its own high or critical advisory that no single upgrade fixes. A problem that's only
  // in a dependency is never enough, because a reviewer may be able to work around it.
  if (rejectReasons.length === 0 && verdict === "AVOID") {
    const facts = [];
    if (evidence.isDeprecated) {
      facts.push(evidence.package + " is deprecated" + quoted(evidence.deprecatedReason));
    }
    if (ownUnfixed) {
      facts.push(evidence.package + " has high or critical advisories that no single upgrade fixes");
    }
    if (facts.length > 0) {
      // e.g. 'the AI verdict is AVOID, and ua-parser-js@1.0.2 is deprecated ("…")'
      rejectReasons.push("the AI verdict is AVOID, and " + facts.join(", and "));
    }
  }

  // ---- The route ----

  // A fact that rules the package out comes first. Approval needs every rule to pass.
  // Everything in between goes to a human.
  let route = "HUMAN_REVIEW";
  if (rejectReasons.length > 0) {
    route = "AUTO_REJECT";
  } else if (reasons.length === 0) {
    route = "AUTO_APPROVE";
  }

  return {
    verdict: verdict,
    llmOutputValid: llmOutputValid,
    highOrCriticalAdvisories: highOrCritical,
    route: route,
    routeReasons: reasons,
    rejectReasons: rejectReasons
  };
}

applyRoutingRules();

// write_brief: builds the markdown brief that the reviewer sees in the Human task form and
// that's posted to GitHub. It combines the AI's words with facts the workflow computed.
//
// Inputs:  $.evidenceText   the evidence pack from build_evidence_pack, as JSON text
//          $.assessment     the AI's answer: verdict, summary, risks, conditions
//          $.verdict, $.llmOutputValid, $.route, $.routeReasons, $.rejectReasons
//                           from apply_routing_rules
// Output:  briefMarkdown, plus its parts (summary, risks, conditions, dependencyRisks)
//
// The brief, in order:
//   1. AI verdict, recommended version, and routing
//   2. The AI's summary
//   3. Risks (from the AI)
//   4. Dependencies with known advisories (from the evidence, never from the AI)
//   5. Conditions (from the AI)
//   6. Security community reports (Hacker News stories, information only)
//   7. Evidence: the key facts
//
// Notes on Conductor:
// - The last line calls writeBrief(); what it returns becomes the task output.
//   Everything else is inside functions, because a top-level const or let can fail when
//   Conductor reuses a script context.
// - Text is joined with + because Conductor treats a dollar sign followed by a brace in a
//   task input as a workflow reference, which rules out JavaScript template literals.
// - The evidence arrives as JSON text, so JSON.parse gives plain JavaScript objects and arrays.
//   The AI's lists and the routing reasons arrive as Java lists, so toTextList copies them.

// ---- Helpers ----

// Copies up to max items from a Java list (or a single string) into a JavaScript array of text.
function toTextList(list, max) {
  const items = [];
  if (list === null || list === undefined) {
    return items;
  }
  if (typeof list === "string") {
    items.push(list);
    return items;
  }
  for (let i = 0; i < list.length && i < max; i++) {
    items.push(String(list[i]));
  }
  return items;
}

// plural(1, "package", "packages") -> "1 package"
function plural(count, one, many) {
  if (count === 1) {
    return count + " " + one;
  }
  return count + " " + many;
}

// 878512 -> "878,512"
function withCommas(number) {
  const digits = String(number);
  let result = "";
  for (let i = 0; i < digits.length; i++) {
    // Add a comma before each group of three digits, counting from the right.
    if (i > 0 && (digits.length - i) % 3 === 0) {
      result += ",";
    }
    result += digits[i];
  }
  return result;
}

function isHighOrCritical(advisory) {
  return advisory.severity === "HIGH" || advisory.severity === "CRITICAL";
}

// Adds a blank line, a bold heading and one bullet per item (nothing if there are no items).
function addSection(lines, heading, items) {
  if (items.length === 0) {
    return;
  }
  lines.push("");
  lines.push(heading);
  for (const item of items) {
    lines.push("- " + item);
  }
}

// e.g. "auto-approved by policy"
//      "auto-rejected by policy because request is deprecated by its maintainers, including its latest version 2.88.2 (…)"
//      "human review because AI verdict is AVOID; 25 package(s) have unknown or non-standard licenses"
function describeRoute(route, routeReasons, rejectReasons) {
  if (route === "AUTO_APPROVE") {
    return "auto-approved by policy";
  }
  if (route === "AUTO_REJECT") {
    return "auto-rejected by policy because " + rejectReasons.join("; ");
  }
  return "human review because " + routeReasons.join("; ");
}

// Up to 5 packages and 3 licenses each, e.g. "inherits@2.0.3 (ISC), qs@6.7.0 (BSD-3-Clause)".
function listPackages(items) {
  const parts = [];
  for (const item of items.slice(0, 5)) {
    let licenses = item.licenses.slice(0, 3).join(", ");
    if (licenses === "") {
      licenses = "none";
    }
    parts.push(item.package + " (" + licenses + ")");
  }
  return parts.join(", ");
}

// e.g. "License policy (no allowlist, so any recognized license is accepted): every package has a recognized license"
//      "License policy: 3 outside policy: inherits@2.0.3 (ISC), setprototypeof@1.1.1 (ISC), qs@6.7.0 (BSD-3-Clause)"
function describeLicensePolicy(policy) {
  let label = "License policy";
  if (policy.mode === "any") {
    label = "License policy (no allowlist, so any recognized license is accepted)";
  }

  if (policy.violationCount === 0 && policy.unknownCount === 0) {
    if (policy.mode === "any") {
      return label + ": every package has a recognized license";
    }
    return label + ": all licenses allowed";
  }

  const problems = [];
  if (policy.violationCount > 0) {
    problems.push(policy.violationCount + " outside policy: " + listPackages(policy.violations));
  }
  if (policy.unknownCount > 0) {
    problems.push(policy.unknownCount + " unknown: " + listPackages(policy.unknown));
  }
  return label + ": " + problems.join("; ");
}

// e.g. "verified build from github.com/axios/axios at commit 84a9f3b"
//      "none published (common, and not a risk by itself)"
function describeProvenance(provenance) {
  if (provenance.status === "verified") {
    let text = "verified build from " + provenance.builtFromRepo;
    if (provenance.commit) {
      text += " at commit " + provenance.commit.substring(0, 7);
    }
    return text;
  }
  if (provenance.status === "repo_mismatch") {
    return "WARNING: attestation says it was built from " + provenance.builtFromRepo +
      ", but the listed source repo is " + provenance.listedSourceRepo;
  }
  if (provenance.status === "unverified") {
    return "WARNING: an attestation exists but could not be verified";
  }
  return "none published (common, and not a risk by itself)";
}

// ---- The brief ----

function writeBrief() {
  const evidence = JSON.parse($.evidenceText);
  const deps = evidence.transitiveDependencies;

  // If the model returned text instead of JSON, try to parse it.
  let assessment = $.assessment || {};
  if (typeof assessment === "string") {
    try {
      assessment = JSON.parse(assessment);
    } catch (e) {
      assessment = {};
    }
  }

  const lines = [];

  // ---- 1. AI verdict, recommended version, and routing ----

  // e.g. "**AI verdict:** ADOPT_WITH_CONDITIONS"
  let verdictLine = "**AI verdict:** " + $.verdict;
  if (!$.llmOutputValid) {
    verdictLine += " (model output was invalid, so a human must decide)";
  }
  lines.push(verdictLine);

  // e.g. "**Recommended version:** 4.20.0 (the lowest 4.x release that fixes both advisories on express; …)"
  let recommended = evidence.upgrade.recommendedVersion;
  if (!recommended) {
    recommended = "n/a";
  }
  lines.push("**Recommended version:** " + recommended +
    " (" + evidence.upgrade.explanation + "; computed by the workflow, not the LLM)");

  // e.g. "**Routing:** human review because AI verdict is ADOPT_WITH_CONDITIONS; …"
  const routeReasons = toTextList($.routeReasons, 20);
  const rejectReasons = toTextList($.rejectReasons, 5);
  lines.push("**Routing:** " + describeRoute($.route, routeReasons, rejectReasons));

  // ---- 2. The AI's summary ----

  let summary = "";
  if (assessment.summary) {
    summary = String(assessment.summary);
  }
  lines.push("");
  if (summary) {
    lines.push(summary);
  } else {
    lines.push("The model did not return a summary.");
  }

  // ---- 3. Risks (from the AI) ----

  // e.g. "express@4.17.1: open redirect (GHSA-rv95-896h-c2vc, MODERATE)"
  const risks = toTextList(assessment.risks, 6);
  addSection(lines, "**Risks**", risks);

  // ---- 4. Dependencies with known advisories (from the evidence, never from the AI) ----

  const dependencyLines = [];
  for (const dep of deps.packagesWithAdvisories) {
    // e.g. "nodemailer@9.0.1: 7 known advisories (2 HIGH, 5 MODERATE), fixed in 10.0.6 (new major version): GHSA-2x7j-588g-ccc2, …"
    let line = dep.package + ": " + plural(dep.advisoryCount, "known advisory", "known advisories");
    line += " (" + dep.severity + "), " + dep.fix + ": ";

    // The advisory IDs, plus "+N more" if the evidence lists only the first 10.
    const ids = [];
    for (const advisory of dep.advisories) {
      ids.push(advisory.id);
    }
    if (dep.advisoryCount > ids.length) {
      ids.push("+" + (dep.advisoryCount - ids.length) + " more");
    }
    line += ids.join(", ");

    // High and critical advisories also get their own sub-line, e.g.
    //   "  - HIGH GHSA-v53p-9fqp-m79j: Nodemailer: Quadratic backtracking in the addressparser …"
    for (const advisory of dep.advisories) {
      if (isHighOrCritical(advisory)) {
        line += "\n  - " + advisory.severity + " " + advisory.id + ": " + advisory.summary;
      }
    }

    dependencyLines.push(line);
  }

  // The evidence lists the 15 most severe; say how many more there are.
  // e.g. "...and 17 more dependencies with known advisories"
  const notListed = deps.packagesWithAdvisoriesCount - deps.packagesWithAdvisories.length;
  if (notListed > 0) {
    dependencyLines.push("...and " + notListed + " more dependencies with known advisories");
  }
  addSection(lines, "**Dependencies with known advisories** (computed by the workflow)", dependencyLines);

  // ---- 5. Conditions (from the AI) ----

  // e.g. "Upgrade express to 4.20.0 or later."
  const conditions = toTextList(assessment.conditions, 6);
  addSection(lines, "**Conditions**", conditions);

  // ---- 6. Security community reports (Hacker News stories, information only) ----

  const reportLines = [];
  for (const report of evidence.communityReports || []) {
    // e.g. "2021-10-25: Malware Discovered in Popular NPM Package, ua-parser-JS (us-cert.cisa.gov, 18 points, before this release) https://…"
    let line = report.date + ": " + report.title + " (" + report.source + ", " + plural(report.points, "point", "points");
    if (report.namesThisVersion) {
      line += ", names this version";
    }
    if (report.postedAfterRelease === true) {
      line += ", after this release";
    } else if (report.postedAfterRelease === false) {
      line += ", before this release";
    }
    line += ")";
    if (report.url) {
      line += " " + report.url;
    }
    line += " (discussion: " + report.discussion + ")";
    reportLines.push(line);
  }
  addSection(lines, "**Security community reports** (Hacker News stories; unverified, information only)", reportLines);

  // ---- 7. Evidence ----

  const evidenceLines = [];

  // e.g. "Advisories affecting this version: 2 (0 high/critical)"
  let ownHighOrCritical = 0;
  for (const advisory of evidence.advisories) {
    if (isHighOrCritical(advisory)) {
      ownHighOrCritical++;
    }
  }
  evidenceLines.push("Advisories affecting this version: " + evidence.advisories.length +
    " (" + ownHighOrCritical + " high/critical)");

  // e.g. "Dependencies: 1321 (60 direct, 1261 indirect)", plus "; only 199 checked" if some weren't
  let dependencies = "Dependencies: " + deps.total + " (" + deps.direct + " direct, " + deps.indirect + " indirect)";
  if (deps.checked < deps.total) {
    dependencies += "; only " + deps.checked + " checked";
  }
  evidenceLines.push(dependencies);

  // e.g. "Advisories in dependencies: 13 across 5 packages (4 HIGH, 9 MODERATE; listed above)"
  let dependencyAdvisories = "Advisories in dependencies: " + deps.uniqueAdvisoryCount;
  if (deps.packagesWithAdvisoriesCount > 0) {
    let severity = deps.advisorySeverity;
    if (!severity) {
      severity = "severity unknown";
    }
    if (!deps.severityComplete) {
      severity += "; severity details incomplete";
    }
    dependencyAdvisories += " across " + plural(deps.packagesWithAdvisoriesCount, "package", "packages") +
      " (" + severity + "; listed above)";
  }
  evidenceLines.push(dependencyAdvisories);

  evidenceLines.push(describeLicensePolicy(evidence.licensePolicy));
  evidenceLines.push("Provenance: " + describeProvenance(evidence.provenance));

  // e.g. "Package license: MIT"
  let packageLicense = evidence.licenses.join(", ");
  if (packageLicense === "") {
    packageLicense = "unknown";
  }
  evidenceLines.push("Package license: " + packageLicense);

  // e.g. "OpenSSF Scorecard: 8.5/10"
  let scorecard = "n/a";
  if (evidence.project && evidence.project.scorecardOverall !== null) {
    scorecard = evidence.project.scorecardOverall + "/10";
  }
  evidenceLines.push("OpenSSF Scorecard: " + scorecard);

  // e.g. "Monthly npm downloads: 585,410,126"
  let downloads = "n/a";
  if (evidence.monthlyDownloads) {
    downloads = withCommas(evidence.monthlyDownloads);
  }
  evidenceLines.push("Monthly npm downloads: " + downloads);

  // e.g. "Hacker News security stories: 5 (listed above): 4 posted before this release, 1 after",
  //      "none found", or "not checked …"
  let community = "none found";
  if (!evidence.communityReports) {
    community = "not checked (the Hacker News search failed)";
  } else if (evidence.communityReports.length > 0) {
    community = evidence.communityReports.length + " (listed above)";
    let before = 0;
    let after = 0;
    for (const report of evidence.communityReports) {
      if (report.postedAfterRelease === false) {
        before++;
      } else if (report.postedAfterRelease === true) {
        after++;
      }
    }
    if (before + after > 0) {
      community += ": " + before + " posted before this release, " + after + " after";
    }
  }
  evidenceLines.push("Hacker News security stories: " + community);

  // e.g. "Missing sources: DeepWiki (MCP)"
  let missing = evidence.missingSources.join(", ");
  if (missing === "") {
    missing = "none";
  }
  evidenceLines.push("Missing sources: " + missing);

  addSection(lines, "**Evidence**", evidenceLines);

  return {
    summary: summary,
    risks: risks,
    conditions: conditions,
    dependencyRisks: dependencyLines,
    briefMarkdown: lines.join("\n")
  };
}

writeBrief();
